"""Contract tests for the feedstocks generated by the ctt answer sets."""

import hashlib

from conftest import ROOT, Feedstock


def test_generated_feedstock_uses_record_and_replay_shape(feedstock: Feedstock) -> None:
    """The generated project exposes the resolved record and replay contract."""
    dataset_name = feedstock.answers["dataset_name"]
    recipe = feedstock.read("bookshelf.yaml")
    build = feedstock.read("build.py")
    pyproject = feedstock.read("pyproject.toml")
    ruff = feedstock.read("ruff.toml")
    makefile = feedstock.read("Makefile")

    assert f"collection: {dataset_name}" in recipe
    assert "visibility: public" in recipe
    assert "notebook: build.py" in recipe
    assert 'version = "v0.1.0"' in build
    assert 'input_sha256 = "sha256:' in build
    assert 'Path(".cache")' in build
    assert "import bookshelf" in build
    assert "client, draft = bookshelf.setup(version=version)" in build
    assert "visibility=" not in build
    assert "with client.activity(" in build
    assert "raw = activity.register(" in build
    assert "data = activity.register(" in build
    assert 'draft.attach(data, name_in_book="data")' in build
    assert "draft.publish()" in build
    assert "asyncio" not in build
    assert "async def" not in build
    assert "await " not in build
    assert "used=[raw.tracking_id]" in build
    assert '"bookshelf[publish,dataframes]"' in pyproject
    assert "climate-resource/bookshelf" in pyproject
    assert 'branch = "feat/adopt-bookshelf-sdk"' in pyproject
    assert '"build.py" = [' in ruff
    assert '"E402"' in ruff
    assert 'src = [\n    ".",' in ruff
    assert 'known-first-party = [\n    "build",' in ruff
    assert "uv run bookshelf record --force" in makefile
    assert "uv run bookshelf validate" in makefile
    assert "uv run bookshelf publish" in makefile
    assert "uv run bookshelf publish --dry-run" in makefile


def test_generated_build_file_names_the_dataset_everywhere_it_matters(
    feedstock: Feedstock,
) -> None:
    """The cache file, the logical keys and the namespace all follow the answers."""
    dataset_name = feedstock.answers["dataset_name"]
    build = feedstock.read("build.py")

    assert f'Path(".cache") / "{dataset_name}.csv"' in build
    assert f'logical_key=f"{dataset_name}/raw-{{version}}"' in build
    assert f'logical_key=f"{dataset_name}/data-{{version}}"' in build

    namespace = feedstock.build_assignments("resource_namespace")
    assert namespace["resource_namespace"] == feedstock.answers["project_url"]


def test_generated_feedstock_carries_no_python_beyond_the_build_file(
    feedstock: Feedstock,
) -> None:
    """The CLI owns record, validate and replay, so a feedstock ships no scripts."""
    shipped = [path for path in feedstock.shipped() if path.endswith(".py")]

    assert not (feedstock.path / "scripts").exists()
    assert shipped == ["build.py"]


def test_generated_example_input_matches_its_declared_content_hash(
    feedstock: Feedstock,
) -> None:
    """The cached example input is independently verified by the contract test."""
    assignments = feedstock.build_assignments("input_content", "input_sha256")

    actual = "sha256:" + hashlib.sha256(assignments["input_content"]).hexdigest()
    assert actual == assignments["input_sha256"]


def test_generated_example_input_is_seeded_with_the_dataset_name(
    feedstock: Feedstock,
) -> None:
    """Registration deduplicates on content, so the example differs per feedstock."""
    assignments = feedstock.build_assignments("input_content")

    assert feedstock.answers["dataset_name"].encode() in assignments["input_content"]


def test_example_inputs_never_collide_between_feedstocks(
    feedstocks: list[Feedstock],
) -> None:
    """Two feedstocks must not register byte identical example resources.

    Registration deduplicates on content, so a shared example aliases onto whichever
    feedstock published it first, and the second one can then not attach it.
    """
    contents = [
        generated.build_assignments("input_content")["input_content"]
        for generated in feedstocks
    ]
    declared = [
        generated.build_assignments("input_sha256")["input_sha256"]
        for generated in feedstocks
    ]

    assert len(set(contents)) == len(contents)
    assert len(set(declared)) == len(declared)


def test_resource_namespaces_never_collide_between_feedstocks(
    feedstocks: list[Feedstock],
) -> None:
    """Tracking identifiers derive from the namespace, so it has to be unique."""
    namespaces = [
        generated.build_assignments("resource_namespace")["resource_namespace"]
        for generated in feedstocks
    ]

    assert len(set(namespaces)) == len(namespaces)


def test_generated_feedstock_calls_reusable_workflows(feedstock: Feedstock) -> None:
    """The generated project owns triggers and delegates workflow implementation."""
    ci = feedstock.read(".github/workflows/feedstock-ci.yaml")
    publish = feedstock.read(".github/workflows/feedstock-publish.yaml")

    assert "pull_request:" in ci
    assert "push:" in ci
    assert "schedule:" in ci
    assert (
        "climate-resource/copier-bookshelf-dataset/.github/workflows/"
        "feedstock-ci.yaml@HEAD" in ci
    )
    assert "release:" in publish
    assert "workflow_dispatch:" in publish
    assert (
        "climate-resource/copier-bookshelf-dataset/.github/workflows/"
        "feedstock-publish.yaml@HEAD" in publish
    )
    assert "secrets: inherit" in publish
    assert "BOOKSHELF_CLIENT_ID:" not in publish
    assert "BOOKSHELF_CLIENT_SECRET:" not in publish


def test_caller_templates_derive_the_reusable_workflow_ref() -> None:
    """A caller uses Copier's selected ref, with its resolved commit as fallback."""
    template_workflows = ROOT / "template" / ".github" / "workflows"

    for name in ("feedstock-ci.yaml.jinja", "feedstock-publish.yaml.jinja"):
        caller = (template_workflows / name).read_text()
        assert "_copier_conf.vcs_ref or _copier_answers._commit" in caller


def test_template_keeps_the_generated_lock_file_under_version_control() -> None:
    """CI syncs a feedstock with --locked, so its lock file has to be committed."""
    ignored = (ROOT / "template" / ".gitignore").read_text().splitlines()

    assert "uv.lock" not in {line.strip() for line in ignored}


def test_this_repository_ignores_every_generated_lock_file() -> None:
    """The fixtures relock on each run, so a committed copy would pin an SDK commit."""
    ignored = (ROOT / ".gitignore").read_text().splitlines()

    assert "tests/regression/ctt/*/uv.lock" in {line.strip() for line in ignored}


def test_every_answer_set_generates_the_same_files(feedstocks: list[Feedstock]) -> None:
    """No answer adds or drops a file, because nothing in the template is optional."""
    shipped = {generated.name: generated.shipped() for generated in feedstocks}
    reference = shipped[min(shipped)]

    assert all(files == reference for files in shipped.values())
    assert "build.py" in reference
